package com.agacostays.billing.controller;import com.agacostays.billing.dto.response.*;import com.agacostays.billing.service.InvoiceService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/invoices") public class InvoiceController{private final InvoiceService s;public InvoiceController(InvoiceService s){this.s=s;}@PostMapping("/bills/{billId}")public ResponseEntity<ApiResponse<InvoiceResponse>> gen(@PathVariable Long billId){return ResponseEntity.ok(ApiResponse.ok("Invoice generated",s.generate(billId)));}@GetMapping("/{invoiceId}")public ResponseEntity<ApiResponse<InvoiceResponse>> get(@PathVariable Long invoiceId){return ResponseEntity.ok(ApiResponse.ok("Invoice fetched",s.get(invoiceId)));}@GetMapping("/{invoiceId}/download")public ResponseEntity<byte[]> download(@PathVariable Long invoiceId){return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=invoice-"+invoiceId+".txt").body(s.download(invoiceId));}}
